import { getSchema, type JSONContent } from "@tiptap/core";
import { createRichExtensions } from "./rich-extensions";

type RichDocumentValue = { version: 1; content: JSONContent };
type DocumentReference = {
    kind: "person" | "document" | "task";
    id: string;
    label: string;
    inaccessible?: boolean;
    disabled?: boolean;
};
type RichDocumentHeading = { id: string; label: string; depth: 1 | 2 | 3 };

const schema = getSchema(createRichExtensions());

function validateRichDocument(value: RichDocumentValue): void {
    if (!value || value.version !== 1 || value.content?.type !== "doc") {
        throw new TypeError("Rich document requires version 1 and a doc node.");
    }
    const ids = new Set<string>();
    function visit(node: JSONContent, path: string) {
        if (!node || !node.type || !schema.nodes[node.type]) {
            throw new TypeError(`Unknown node at ${path}.`);
        }
        if (node.type !== "text" && node.text !== undefined ||
            node.type === "text" && node.content !== undefined) {
            throw new TypeError(`Invalid text/content property at ${path}.`);
        }
        const spec = schema.nodes[node.type].spec;
        for (const key of Object.keys(node)) {
            if (!["type", "attrs", "content", "marks", "text"].includes(key)) {
                throw new TypeError(`Unknown property ${path}.${key}.`);
            }
        }
        for (const key of Object.keys(node.attrs ?? {})) {
            if (!Object.hasOwn(spec.attrs ?? {}, key)) {
                throw new TypeError(`Unknown attribute ${path}.${key}.`);
            }
        }
        const id = node.attrs?.nodeId;
        if (id != null) {
            if (typeof id !== "string" || !id.trim() || ids.has(id)) {
                throw new TypeError(`Invalid or duplicate nodeId at ${path}.`);
            }
            ids.add(id);
        }
        if (node.type === "heading" &&
            ![1, 2, 3].includes(node.attrs?.level ?? 1)) {
            throw new TypeError("Heading level must be 1, 2, or 3.");
        }
        if (node.type === "mention" && (
            !["person", "document", "task"].includes(node.attrs?.kind) ||
            typeof node.attrs?.id !== "string" || !node.attrs.id.trim()
        )) throw new TypeError("Reference needs a stable kind and ID.");
        if (node.type === "image" && (
            typeof node.attrs?.src !== "string" ||
            !/^(https?:\/\/|\/|\.\/|\.\.\/)/i.test(node.attrs.src) ||
            node.attrs.src.startsWith("//")
        )) throw new TypeError("Image requires an HTTP or relative URL.");
        for (const mark of node.marks ?? []) {
            if (mark.type === "link" && mark.attrs?.href &&
                !/^(https?:\/\/|mailto:|\/[^/]|#)/i.test(mark.attrs.href)) {
                throw new TypeError("Link requires a safe URL or internal path.");
            }
            const type = schema.marks[mark.type];
            if (!type) throw new TypeError(`Unknown mark ${mark.type}.`);
            for (const key of Object.keys(mark.attrs ?? {})) {
                if (!Object.hasOwn(type.spec.attrs ?? {}, key)) {
                    throw new TypeError(`Unknown mark attribute ${key}.`);
                }
            }
        }
        node.content?.forEach((child, index) =>
            visit(child, `${path}.content[${index}]`));
    }
    visit(value.content, "content");
    schema.nodeFromJSON(value.content).check();
}

function extractRichDocumentHeadings(value: RichDocumentValue) {
    validateRichDocument(value);
    const headings: RichDocumentHeading[] = [];
    function text(node: JSONContent): string {
        return node.text ?? node.content?.map(text).join("") ?? "";
    }
    function visit(node: JSONContent) {
        if (node.type === "heading" && node.attrs?.nodeId) {
            headings.push({
                id: node.attrs.nodeId, label: text(node),
                depth: node.attrs.level ?? 1,
            });
        }
        node.content?.forEach(visit);
    }
    visit(value.content);
    return headings;
}

/** Materializes schema defaults without changing stable node/reference IDs. */
function normalizeRichDocument(value: RichDocumentValue): RichDocumentValue {
    validateRichDocument(value);
    return { version: 1, content: JSON.parse(JSON.stringify(
        schema.nodeFromJSON(value.content).toJSON(),
    )) };
}

export { validateRichDocument, extractRichDocumentHeadings, normalizeRichDocument };
export type { RichDocumentValue, RichDocumentHeading, DocumentReference };

import { Node, mergeAttributes } from "@tiptap/core";
import StarterKit from "@tiptap/starter-kit";
import UniqueID from "@tiptap/extension-unique-id";
import { TaskList, TaskItem } from "@tiptap/extension-list";
import { TableKit } from "@tiptap/extension-table";
import Image from "@tiptap/extension-image";
import Mention from "@tiptap/extension-mention";

const Callout = Node.create({
    name: "callout",
    group: "block",
    content: "block+",
    defining: true,
    addAttributes() {
        return { tone: { default: "info" } };
    },
    parseHTML() { return [{ tag: "aside[data-callout]" }]; },
    renderHTML({ HTMLAttributes }) {
        return ["aside", mergeAttributes(HTMLAttributes, {
            "data-callout": HTMLAttributes.tone, role: "note",
            class: "rounded-md border border-border bg-surface-subtle p-3",
        }), 0];
    },
});

type ReferenceDisplay = { label: string; disabled?: boolean; inaccessible?: boolean };
type ReferenceViewOptions = {
    resolve?: (kind: string, id: string) => ReferenceDisplay | undefined;
    subscribe?: (refresh: () => void) => () => void;
    onOpen?: (kind: string, id: string) => void;
};

function referenceExtension(options: ReferenceViewOptions) {
    return Mention.extend({
    addNodeView() {
        return ({ node }) => {
            let current = node;
            const dom = document.createElement("span");
            dom.className = "cursor-pointer rounded-sm bg-surface-subtle px-1";
            dom.contentEditable = "false";
            dom.setAttribute("role", "link");
            dom.tabIndex = 0;
            function refresh() {
                const reference = options.resolve?.(current.attrs.kind, current.attrs.id);
                const unavailable = !reference || reference.disabled || reference.inaccessible;
                dom.dataset.type = "mention";
                dom.dataset.referenceId = current.attrs.id;
                dom.dataset.referenceKind = current.attrs.kind;
                if (current.attrs.nodeId) dom.id = current.attrs.nodeId;
                dom.textContent = unavailable ? "접근할 수 없는 참조" : `@${reference.label}`;
                dom.setAttribute("aria-disabled", String(Boolean(unavailable)));
                dom.setAttribute("aria-label", unavailable
                    ? "접근할 수 없는 참조" : `${reference.label} 열기`);
            }
            function activate(event: KeyboardEvent) {
                if (event.isComposing || event.keyCode === 229 ||
                    event.key !== "Enter" && event.key !== " ") return;
                event.preventDefault();
                event.stopPropagation();
                const reference = options.resolve?.(
                    current.attrs.kind, current.attrs.id,
                );
                if (!reference || reference.disabled || reference.inaccessible)
                    return;
                options.onOpen?.(current.attrs.kind, current.attrs.id);
            }
            dom.addEventListener("keydown", activate);
            refresh();
            const unsubscribe = options.subscribe?.(refresh);
            return {
                dom,
                update(next) {
                    if (next.type !== current.type) return false;
                    current = next; refresh(); return true;
                },
                // The atom's display belongs to this NodeView, not document text.
                ignoreMutation: () => true,
                stopEvent: (event) => event.type === "keydown" &&
                    event instanceof KeyboardEvent &&
                    (event.key === "Enter" || event.key === " ") &&
                    !event.isComposing && event.keyCode !== 229,
                destroy: () => {
                    dom.removeEventListener("keydown", activate);
                    unsubscribe?.();
                },
            };
        };
    },
    addAttributes() {
        return {
            ...this.parent?.(),
            kind: { default: "document" },
        };
    },
    renderHTML({ node, HTMLAttributes }) {
        return ["span", mergeAttributes(HTMLAttributes, {
            "data-type": "mention", "data-reference-id": node.attrs.id,
            "data-reference-kind": node.attrs.kind,
            class: "cursor-pointer rounded-sm bg-surface-subtle px-1",
        }), `@${node.attrs.label ?? node.attrs.id}`];
    },
});

}

const StableID = UniqueID.extend({
    addGlobalAttributes() {
        return [{ types: this.options.types, attributes: {
            [this.options.attributeName]: {
                default: null,
                parseHTML: (element) => element.getAttribute("data-node-id"),
                renderHTML: (attributes) => attributes.nodeId ? {
                    "data-node-id": attributes.nodeId, id: attributes.nodeId,
                } : {},
            },
        } }];
    },
});

function createRichExtensions(options: ReferenceViewOptions = {}) {
    return [
        StarterKit.configure({ heading: { levels: [1, 2, 3] } }),
        TaskList, TaskItem.configure({ nested: true }),
        TableKit.configure({ table: { resizable: false } }),
        Image.configure({ allowBase64: false }),
        referenceExtension(options).configure({ suggestion: { char: "\u0000" } }),
        Callout,
        StableID.configure({
            attributeName: "nodeId",
            types: [
                "paragraph", "heading", "blockquote", "codeBlock",
                "bulletList", "orderedList", "listItem", "taskList",
                "taskItem", "table", "tableRow", "tableCell",
                "tableHeader", "image", "mention", "callout",
                "horizontalRule",
            ],
        }),
    ];
}

export { createRichExtensions };

import { Plugin, PluginKey } from "@tiptap/pm/state";
import { Decoration, DecorationSet } from "@tiptap/pm/view";
import type { ThreadComment } from "../thread";

type InlineComment = {
    id: string;
    from: number;
    to: number;
    quote: string;
    status: "open" | "resolved";
    anchor: "attached" | "orphaned";
    comments: readonly ThreadComment[];
};

function createCommentPlugin(initial: readonly InlineComment[]) {
    const key = new PluginKey<readonly InlineComment[]>("richComments");
    const plugin = new Plugin<readonly InlineComment[]>({
        key,
        state: {
            init: () => initial,
            apply(transaction, previous, _old, state) {
                const replacement = transaction.getMeta(key);
                if (replacement) return replacement as InlineComment[];
                if (!transaction.docChanged) return previous;
                const size = state.doc.content.size;
                const clamp = (pos: number) => Math.max(0, Math.min(size, pos));
                return previous.map<InlineComment>((item) => {
                    const start = item.anchor === "orphaned" ? item.from :
                        transaction.mapping.map(item.from, 1);
                    const end = item.anchor === "orphaned" ? item.to :
                        transaction.mapping.map(item.to, -1);
                    const from = clamp(Math.min(start, end));
                    const to = clamp(Math.max(start, end));
                    const orphaned = item.anchor === "orphaned" ||
                        from === to || !state.doc.textBetween(from, to);
                    return {
                        ...item, from, to,
                        anchor: orphaned ? "orphaned" : "attached",
                    };
                });
            },
        },
        props: {
            decorations(state) {
                return DecorationSet.create(state.doc,
                    (key.getState(state) ?? []).filter((item) =>
                        item.anchor === "attached" && item.status === "open" &&
                        item.from < item.to && item.to <= state.doc.content.size
                    ).map((item) => Decoration.inline(item.from, item.to, {
                        class: "bg-surface-subtle underline decoration-accent",
                        "data-comment-id": item.id,
                    })),
                );
            },
        },
    });
    return { key, plugin };
}

export { createCommentPlugin };
export type { InlineComment };

import type { JSONContent } from "@tiptap/core";
import type { BlockEditorBlock, BlockKind } from "./legacy-types";
import { validateRichDocument, type RichDocumentValue } from "./rich-document";

type ConversionLoss = { path: string; reason: string };
type LegacyConversionResult =
    | { ok: true; blocks: BlockEditorBlock[] }
    | { ok: false; losses: ConversionLoss[] };

function legacyBlocksToRichDocument(
    blocks: readonly BlockEditorBlock[],
): RichDocumentValue {
    const ids = new Set<string>();
    const kinds = ["paragraph", "heading", "subheading", "bullet", "number",
        "quote", "code"];
    for (const block of blocks) {
        if (!block.id.trim() || ids.has(block.id) || !kinds.includes(block.kind)
            || typeof block.text !== "string") {
            throw new TypeError("Legacy blocks need unique IDs, kinds and text.");
        }
        ids.add(block.id);
    }
    function allocate(base: string) {
        let id = base;
        let suffix = 1;
        while (ids.has(id)) id = `${base}-${suffix++}`;
        ids.add(id);
        return id;
    }
    function inline(text: string): JSONContent[] {
        return text.split("\n").flatMap((line, index) => [
            ...(index ? [{ type: "hardBreak" }] : []),
            ...(line ? [{ type: "text", text: line }] : []),
        ]);
    }
    function paragraph(text: string, id: string): JSONContent {
        return { type: "paragraph", attrs: { nodeId: id }, content: inline(text) };
    }
    const content: JSONContent[] = [];
    for (let index = 0; index < blocks.length; index += 1) {
        const block = blocks[index];
        if (block.kind === "bullet" || block.kind === "number") {
            const list: JSONContent = {
                type: block.kind === "bullet" ? "bulletList" : "orderedList",
                attrs: { nodeId: allocate(`${block.id}-list`) }, content: [],
            };
            do {
                const item = blocks[index];
                list.content!.push({
                    type: "listItem", attrs: { nodeId: item.id },
                    content: [paragraph(item.text, allocate(`${item.id}-text`))],
                });
                index += 1;
            } while (blocks[index]?.kind === block.kind);
            index -= 1;
            content.push(list);
        } else if (block.kind === "heading" || block.kind === "subheading") {
            content.push({ type: "heading", attrs: {
                nodeId: block.id, level: block.kind === "heading" ? 2 : 3,
            }, content: inline(block.text) });
        } else if (block.kind === "quote") {
            content.push({ type: "blockquote", attrs: { nodeId: block.id },
                content: [paragraph(block.text, allocate(`${block.id}-text`))] });
        } else if (block.kind === "code") {
            content.push({ type: "codeBlock", attrs: { nodeId: block.id },
                content: block.text ? [{ type: "text", text: block.text }] : [] });
        } else content.push(paragraph(block.text, block.id));
    }
    // ProseMirror requires at least one block, including an empty document.
    if (!content.length) content.push(paragraph("", allocate("empty")));
    return { version: 1, content: { type: "doc", content } };
}

function richDocumentToLegacyBlocks(
    value: RichDocumentValue,
): LegacyConversionResult {
    validateRichDocument(value);
    const losses: ConversionLoss[] = [];
    const blocks: BlockEditorBlock[] = [];
    function loss(path: string, reason: string) { losses.push({ path, reason }); }
    function attributes(node: JSONContent, allowed: string[], path: string) {
        for (const [key, val] of Object.entries(node.attrs ?? {})) {
            if (allowed.includes(key) || val == null) continue;
            // Schema defaults do not add meaning beyond the legacy model.
            if (node.type === "orderedList" && key === "start" && val === 1)
                continue;
            if (node.type === "orderedList" && key === "type" && val === "1")
                continue;
            loss(path, `Attribute ${key} cannot be represented.`);
        }
        if (node.marks?.length) loss(path, "Inline formatting cannot be represented.");
    }
    function plain(node: JSONContent, path: string): string {
        return (node.content ?? []).map((child, index) => {
            const childPath = `${path}.${index}`;
            if (child.marks?.length) loss(childPath, "Inline formatting is unsupported.");
            if (child.type === "text") return child.text ?? "";
            if (child.type === "hardBreak") return "\n";
            loss(childPath, `Inline ${child.type} is unsupported.`);
            return "";
        }).join("");
    }
    function add(node: JSONContent, kind: BlockKind, text: string, path: string) {
        if (!node.attrs?.nodeId) loss(path, "Stable nodeId is required.");
        else blocks.push({ id: node.attrs.nodeId, kind, text });
    }
    for (const [index, node] of (value.content.content ?? []).entries()) {
        const path = `content.${index}`;
        attributes(node, ["nodeId", ...(node.type === "heading" ? ["level"] : [])], path);
        if (node.type === "paragraph") {
            add(node, "paragraph", plain(node, path), path);
        } else if (node.type === "heading") {
            if (![2, 3].includes(node.attrs?.level)) loss(path, "Heading level has no legacy kind.");
            else add(node, node.attrs?.level === 2 ? "heading" : "subheading", plain(node, path), path);
        } else if (node.type === "codeBlock") {
            add(node, "code", plain(node, path), path);
        } else if (node.type === "blockquote") {
            if (node.content?.length !== 1 || node.content[0].type !== "paragraph")
                loss(path, "Quote needs one plain paragraph.");
            else {
                attributes(node.content[0], ["nodeId"], path);
                add(node, "quote", plain(node.content[0], path), path);
            }
        } else if (node.type === "bulletList" || node.type === "orderedList") {
            for (const item of node.content ?? []) {
                attributes(item, ["nodeId"], path);
                if (item.type !== "listItem" || item.content?.length !== 1 ||
                    item.content[0].type !== "paragraph") {
                    loss(path, "Nested or rich lists cannot be represented.");
                } else {
                    attributes(item.content[0], ["nodeId"], path);
                    add(item, node.type === "bulletList" ? "bullet" : "number",
                        plain(item.content[0], path), path);
                }
            }
        } else loss(path, `Node ${node.type} cannot be represented.`);
    }
    return losses.length ? { ok: false, losses } : { ok: true, blocks };
}

export { legacyBlocksToRichDocument, richDocumentToLegacyBlocks };
export type { ConversionLoss, LegacyConversionResult };

type BlockKind =
    "paragraph" | "heading" | "subheading" | "bullet" |
    "number" | "quote" | "code";

type BlockEditorBlock = {
    id: string;
    kind: BlockKind;
    text: string;
};

export type { BlockKind, BlockEditorBlock };
